@dataclass
class B2CDynamicUpiQrEntity23:
    """Data transfer object for Dynamic NPCI UPI B2C Intent QR Code Generator - Segment 23."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
