@dataclass
class B2CDynamicUpiQrEntity35:
    """Data transfer object for Dynamic NPCI UPI B2C Intent QR Code Generator - Segment 35."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
